function qcalm(){return counsel()}
const cslog=()=>S.cs.m.map(x=>'<div class="csm '+x.r+'">'+(x.r==='a'?'<b>MEDIUS</b>':x.r==='u'?'<b>'+nm().toUpperCase()+'</b>':'')+esc(x.t).replace(/\n/g,'<br>')+'</div>').join('')+(S.cs.busy?'<div class="csm a typing"><b>MEDIUS</b>🕯️ Medius is thinking…</div>':'');
function csPaint(){const c=S.cs,el=$('#counsel');if(!el||!c)return;const v=($('#csin')||{}).value||'';el.outerHTML=counsel();const t=$('#csin');if(t){t.value=c.busy?'':v;if(!c.busy)try{t.focus({preventScroll:true})}catch(e){}}const lg=$('#cslog');if(lg)lg.scrollTop=lg.scrollHeight}
acts.csgo=()=>{csStop();S.cs={ph:'br',sec:0,m:[]};render();musSync();csBreath()};
function csStop(){clearInterval(S.csT);S.csT=0}
function csBreath(){const tick=()=>{const c=S.cs,bu=$('#cnbub');if(!c||c.ph!=='br'||!bu){csStop();return}const p=c.sec%10,inn=p<4;bu.classList.toggle('in',inn);const l=$('#cnbl');if(l)l.textContent=inn?'BREATHE IN':'BREATHE OUT';const s=$('#cnsec');if(s)s.innerHTML=(20-c.sec)+'<small> s</small>';if(st.s.sound&&(p===0||p===4))tn(p?262:392,1.2,'sine',.03);c.sec++;if(c.sec>20)csChat()};tick();S.csT=setInterval(tick,1000)}
acts.csskip=()=>csChat();
function csChat(){csStop();const c=S.cs;if(!c)return;c.ph='chat';if(!c.m.length)c.m.push({r:'a',t:'Well breathed, '+((st.p.name||'').trim()||'traveller')+'. The candle burneth steady and my ears are open. Speak freely: what weigheth upon thee today?'});
if(!c.cr){c.cr=1;st.qd=st.qd||{};st.qd[today()]=1;st.qc=(st.qc||0)+1;save();gain(5,'Wizard\'s Counsel')}render();const lg=$('#cslog');if(lg)lg.scrollTop=lg.scrollHeight}
acts.cssend=()=>{const c=S.cs,el=$('#csin');if(!c||c.busy||!el)return;const t=el.value.trim();if(!t)return;el.value='';c.m.push({r:'u',t:t.slice(0,1500)});if(CRISIS.test(t))c.help=1;csAsk()};
acts.cshelp=()=>{if(S.cs){S.cs.help=!S.cs.help;csPaint()}};
acts.csend=()=>{csStop();S.cs=null;render();musSync()};
async function csAsk(){const c=S.cs;c.busy=1;csPaint();
let msgs=c.m.filter(x=>x.r!=='sys').slice(-30).map(x=>({role:x.r==='u'?'user':'assistant',content:x.t}));while(msgs.length&&msgs[0].role!=='user')msgs.shift();msgs=msgs.reduce((a,x)=>{const l=a[a.length-1];if(l&&l.role===x.role)l.content+='\n\n'+x.content;else a.push(Object.assign({},x));return a},[]);
try{const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-6',max_tokens:1000,system:CSP(),messages:msgs})});if(!r.ok)throw new Error('http '+r.status);const d=await r.json(),t=(d.content||[]).filter(i=>i.type==='text').map(i=>i.text).join('\n').trim();if(!t)throw new Error('empty');c.m.push({r:'a',t})}
catch(e){c.m.push({r:'sys',t:'The candle flickers… Medius cannot reach his spellbook right now (the AI is not connected here or you are offline). Try a few slow breaths, write your thoughts down, and if you need someone now, tap “Need help now?”.'})}
c.busy=0;if(S.cs===c)csPaint()}

/* ---------- Adaptive music (original WebAudio melodies) ---------- */
let MK='home';
const NT=(s,i)=>s[((i%s.length)+s.length)%s.length]*Math.pow(2,Math.floor(i/s.length));
const TRK={home:[430,musTick],
sleep:[650,()=>{const T=[2,1,0,1,2,2,3,2,1,2,null,null,4,3,2,1,0,1,2,1,0,0,null,null],B=[130.81,174.61,130.81,196],k=mi++%T.length,S5=[261.63,293.66,329.63,392,440];if(T[k]!=null)tn(S5[T[k]],1.6,'sine',.05);if(k%3===0)tn(B[(k/6|0)%4],2.2,'sine',.045)}],
water:[270,()=>{const C=[[293.66,369.99,440,587.33],[246.94,293.66,369.99,493.88],[196,246.94,293.66,392],[220,277.18,329.63,440]],k=mi++,ch=C[(k>>3)%4],st8=k%8,n=st8<4?ch[st8]:ch[7-st8];tn(n,.45,'triangle',.035);if(st8===0)tn(ch[0]/2,1.6,'sine',.05)}],
stress:[950,()=>{const T=[0,null,2,null,4,3,null,null,1,null,4,null,2,null,null,null],P=[392,440,523.25,587.33,659.25],k=mi++%T.length;if(T[k]!=null)tn(P[T[k]],2.6,'sine',.04);if(k%8===0)tn(110,7,'sine',.03)}],
counsel:[1900,()=>{const C=[[220,261.63,329.63],[174.61,220,261.63],[130.81,196,261.63],[196,246.94,293.66]],ch=C[mi++%4];ch.forEach(f=>tn(f,3.8,'sine',.016));tn(ch[0]/2,4,'sine',.02)}],
onb:[360,()=>{const T=[0,2,4,7,4,null,5,4,2,0,1,2,null,4,null,null,0,2,4,7,9,7,5,4,2,4,1,null,0,null,null,null],G=[196,220,246.94,261.63,293.66,329.63,369.99,392,440,493.88],k=mi++%T.length;if(T[k]!=null)tn(G[T[k]],.4,'triangle',.06);if(k%4===0)tn([98,130.81,146.83,98][(k/8|0)%4],.9,'triangle',.06)}]};
const trackFor=()=>S.v==='sleep'?'sleep':S.v==='water'?'water':S.v==='stress'?(S.cs?'counsel':'stress'):S.v==='onb'?'onb':'home';
function musSync(){if(!MT)return;const k=trackFor();if(k===MK)return;MK=k;clearInterval(MT);mi=0;TRK[k][1]();MT=setInterval(TRK[k][1],TRK[k][0])}
acts.mus=()=>{if(MT){clearInterval(MT);MT=0}else{MK=trackFor();mi=0;TRK[MK][1]();MT=setInterval(TRK[MK][1],TRK[MK][0])}$('#mus').textContent=MT?'🔊':'🎵'};

